const $ = (selector) => document.querySelector(selector);
const esc = (value) => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selected = records[0].id, activeTab = 'body', evidenceOpen = true, history = [], listScroll = 0, toastTimer;
const tabs = [['body','知识正文'],['relations','关联阅读'],['versions','版本与审核']];
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200)}
function filtered(){if($('#scope').value==='b'||$('#scenario').value!=='normal')return[];const q=$('#search').value.trim().toLowerCase();return records.filter(r=>($('#category').value==='all'||r.category===$('#category').value)&&($('#type').value==='all'||r.type===$('#type').value)&&(!q||[r.title,...r.body,...r.tags].join(' ').toLowerCase().includes(q)))}
function empty(title,description,button=''){return `<div class="empty-state"><div class="empty-glyph" aria-hidden="true">◇</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${button}</div>`}
function renderLibrary(){
 const results=filtered(),unavailable=$('#scenario').value!=='normal',total=$('#scope').value==='a'?records.length:0;
 $('#asset-count').textContent=unavailable?'—':total;$('#match-count').textContent=unavailable?'—':results.length;$('#review-count').textContent=unavailable?'—':$('#scope').value==='a'?records.filter(r=>r.review).length:0;$('#list-count').textContent=unavailable?'状态模拟':`${results.length} 条样例`;
 if(!results.some(r=>r.id===selected)){selected=results[0]?.id||null;activeTab='body';history=[]}
 if(unavailable){const denied=$('#scenario').value==='denied';$('#knowledge-list').innerHTML=empty(denied?'权限不足（模拟）':'加载失败（模拟）',denied?'不展示标题、数量或旧详情。':'读取状态不可确认，不能显示为“0 条知识”。','<button data-recover>恢复正常演示</button>')}
 else $('#knowledge-list').innerHTML=results.length?results.map(r=>`<button class="knowledge-item" data-record="${esc(r.id)}" aria-current="${r.id===selected}"><span class="item-overline"><span>${esc(r.type)}</span><span>样例</span></span><strong>${esc(r.title)}</strong><span class="badge ${r.tone||''}">${esc(r.status)}</span><span class="item-meta">${esc(r.category)} · ${esc(r.date)}</span></button>`).join(''):empty('没有匹配的知识',$('#scope').value==='b'?'演示项目 B 没有资产，项目 A 的详情已清除。':'试试其他关键词，或清空当前筛选。','<button data-clear>清空筛选</button>');
 $('#live-status').textContent=unavailable?'演示不可用状态，旧详情已清除':`筛选命中 ${results.length} 条样例`;
 renderDetail();
}
function evidence(r){if(!evidenceOpen)return'';return `<aside class="evidence-pane" aria-label="证据核对"><div class="section-label"><h3>证据核对</h3><span>样例</span></div>${r.source?`<div class="evidence-index">01 / 原始材料 · 虚构</div><p class="evidence-title">${esc(r.source.name)}</p><span class="badge">原文摘录 · 非生成摘要</span><blockquote class="quote">${esc(r.source.quote)}</blockquote><div class="evidence-meta">定位：${esc(r.source.locator)}<br>来源日期：${esc(r.source.date)}<br>获取时间：${esc(r.source.observed)}<br>材料状态：仅原型内可查看</div><button data-source>查看样例原文 ↗</button>`:`<span class="badge warning">${r.broken?'当前无法访问':'来源待补充'}</span><p class="evidence-title">${r.broken?'原文暂时打不开':'还没有可定位的原始依据'}</p><p class="evidence-meta">${r.broken?'演示失效来源的处理方式，不伪造可用链接或原文。':'未提供来源名称、摘录及位置。不能仅凭这段结论认定证据完整。'}</p><button disabled>暂无可查看原文</button>`}<p class="evidence-caution">来源存在 ≠ 已完成事实核验。正式状态必须来自可追溯的审核记录。</p></aside>`}
function body(r){let warning='';if(r.tone==='danger')warning='<div class="callout danger"><b>冲突待处理 · 演示状态</b>先核对测试条件，不把候选直接当成确定结论。</div>';else if(r.id==='sample-005')warning='<div class="callout"><b>已超出有效期 · 演示状态</b>仅供历史追溯，不能代表当前有效口径。</div>';else if(!r.source)warning='<div class="callout"><b>证据不完整 · 演示状态</b>保留内容，但不标记为已核验。</div>';return `${warning}<p class="body-kicker">${esc(r.origin)}</p><div class="body-text">${r.body.map(p=>`<p>${esc(p)}</p>`).join('')}</div><div class="article-rule"></div><div class="definition"><h3>适用范围</h3><p>${esc(r.scope)}</p></div><div class="definition"><h3>事实有效时间</h3><p>${esc(r.valid)}</p></div><div class="definition"><h3>使用限制</h3><p>${esc(r.limit)}</p></div>`}
function relations(r){return `<p class="relation-caption">明确关系与相似推荐分开呈现。此处全部关系均为演示样例。</p>${r.relations.length?r.relations.map(l=>`<button class="relationship" data-related="${esc(l.id)}"><span class="badge ${l.kind.startsWith('冲突')?'danger':''}">${esc(l.kind)}</span><strong>${esc(l.text)} ↗</strong><small>打开关联样例；可返回当前知识</small></button>`).join(''):empty('关联记录未提供','不能通过内容相似度推断支持、冲突或双向引用。')}<div class="definition"><h3>引用它的报告</h3><p>报告引用记录未提供，不展示推测的引用次数。</p></div>`}
function versions(r){return `<div class="callout info"><b>样例历史，不代表真实版本或审批</b>更新时间与事实有效时间分别保留。</div>${r.versions.length?`<ol class="timeline">${r.versions.map(v=>`<li><b>${esc(v.v)} · ${esc(v.date)}</b><p>${esc(v.text)}</p></li>`).join('')}</ol>`:empty('版本历史未提供','不根据页面加载时间或导入时间生成历史。')}${r.versions.length>1?'<button id="compare-versions" aria-expanded="false">展开 v1 → v2 差异</button><div id="version-diff" class="diff" hidden><del>− v1：围绕用户问题组织上市期内容。</del><ins>+ v2：围绕用户问题组织内容；不据此推断销量增长或订单归因。</ins><p class="evidence-meta">用于说明差异阅读方式，不修改或切换任何版本。</p></div>':''}<div class="article-rule"></div><div class="definition"><h3>审核记录</h3><p>${r.review?'演示审核员 · 人工复核通过（虚构记录）<br>审核时间：'+esc(r.date)+'<br>样例意见：补充适用边界；不把表达建议当成效果归因。':'审核记录未提供。历史资产无记录，不等于审核失败，也不等于已审核。'}</p></div>`}
function renderDetail(){const r=records.find(r=>r.id===selected);if(!r){$('#detail').innerHTML=empty('暂无可查看详情','从当前有权访问的列表选择知识。此处只演示清空旧详情的交互。','<button class="mobile-back" data-back>← 返回知识目录</button>');return}
 $('#detail').innerHTML=`<div class="reader-toolbar"><div><button class="mobile-back" data-back>← 返回目录</button>${history.length?'<button data-history>← 返回上一条</button>':''}<span class="crumb">${esc(r.category)} / ${esc(r.type)}</span></div><button id="toggle-evidence" aria-expanded="${evidenceOpen}">${evidenceOpen?'收起证据栏':'展开证据栏'}</button></div><div class="knowledge-heading"><div class="label-row"><span>${esc(r.id.toUpperCase())} · 交互样例</span><span class="badge ${r.tone||''}">${esc(r.status)}</span></div><h2 id="detail-title" tabindex="-1">${esc(r.title)}</h2><div class="meta-line"><span>${esc(r.version)}</span><span>更新时间：${esc(r.date)}</span><span>演示项目 A · 国内版</span></div></div><div class="reader-tabs" role="tablist" aria-label="知识阅读视图">${tabs.map(([key,name])=>`<button role="tab" id="tab-${key}" data-tab="${key}" aria-selected="${activeTab===key}" tabindex="${activeTab===key?'0':'-1'}" aria-controls="reading-panel">${name}</button>`).join('')}</div><div class="reader-grid ${evidenceOpen?'':'no-evidence'}"><div id="reading-panel" class="reader-content" role="tabpanel" tabindex="0" aria-labelledby="tab-${activeTab}">${activeTab==='body'?body(r):activeTab==='relations'?relations(r):versions(r)}</div>${evidence(r)}</div><div class="future"><span>后续阶段：提交候选 → 证据校验 → 审核 → 生效<br>本原型不开放任何写入操作</span><button disabled title="S3 另行授权">提交候选 · 未开放</button></div>`;
}
function choose(id,related=false){if(!records.some(r=>r.id===id)||$('#scope').value!=='a'||$('#scenario').value!=='normal')return;if(related){history.push({id:selected,tab:activeTab});selected=id;activeTab='body';renderDetail()}else{history=[];selected=id;activeTab='body';listScroll=window.scrollY;renderLibrary()}document.querySelectorAll('[data-record]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.record===id)));$('#workspace').classList.add('show-detail');if(matchMedia('(max-width:760px)').matches)$('#workspace').scrollIntoView({block:'start'});$('#detail-title')?.focus({preventScroll:true});$('#live-status').textContent='已打开样例：'+records.find(r=>r.id===id).title}
function openDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#info-dialog').showModal()}
function clearFilters(){ $('#search').value='';$('#category').value='all';$('#type').value='all';history=[];renderLibrary() }
$('#search').addEventListener('input',()=>{history=[];renderLibrary()});['category','type'].forEach(id=>$('#'+id).addEventListener('change',()=>{history=[];renderLibrary()}));
['scope','scenario'].forEach(id=>$('#'+id).addEventListener('change',()=>{selected=null;history=[];activeTab='body';evidenceOpen=true;$('#workspace').classList.remove('show-detail');if(id==='scope')clearFilters();else renderLibrary()}));
$('#clear-filters').addEventListener('click',clearFilters);$('#close-dialog').addEventListener('click',()=>$('#info-dialog').close());
$('#open-boundary').addEventListener('click',()=>openDialog('这是一份隔离的交互原型','<p>所有标题、正文、日期、证据、关联、版本与审核员均为虚构样例，不读取真实客户资产。</p><p>本次只评审阅读布局、操作与缺失状态。没有连接正式接口，没有保存、导入、删除、审核、发布或修改检索的能力。</p><p>原型不证明租户权限、证据真实性或后台版本链路已经验收；这些属于后续真实接口与业务流验证。</p><p>正式 RAG 资产库和现有导航没有被修改。Obsidian-style 仅用于借鉴关联阅读，不引入另一套产品或知识存储。</p>'));
$('#open-menu').addEventListener('click',()=>openDialog('现有 MMN 导航 · 演示外壳','<div class="dialog-nav">'+$('.global-nav').outerHTML+'</div>'));
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-shell'))toast('这是原型中的既有导航外壳，不切换版本或进入正式模块。');if(b.dataset.record)choose(b.dataset.record);if(b.dataset.related)choose(b.dataset.related,true);if(b.hasAttribute('data-back')){$('#workspace').classList.remove('show-detail');document.querySelector(`[data-record="${selected}"]`)?.focus({preventScroll:true});window.scrollTo({top:listScroll})}if(b.hasAttribute('data-history')){const previous=history.pop();if(previous){selected=previous.id;activeTab=previous.tab;renderDetail();document.querySelectorAll('[data-record]').forEach(x=>x.setAttribute('aria-current',String(x.dataset.record===selected)));$('#detail-title')?.focus({preventScroll:true})}}if(b.dataset.tab){activeTab=b.dataset.tab;renderDetail();$('#tab-'+activeTab).focus()}if(b.id==='toggle-evidence'){evidenceOpen=!evidenceOpen;renderDetail();$('#toggle-evidence').focus()}if(b.hasAttribute('data-clear'))clearFilters();if(b.hasAttribute('data-recover')){$('#scenario').value='normal';renderLibrary()}if(b.id==='compare-versions'){const expanded=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!expanded));b.textContent=expanded?'展开 v1 → v2 差异':'收起版本差异';$('#version-diff').hidden=expanded}if(b.hasAttribute('data-source')){const r=records.find(r=>r.id===selected);openDialog('样例原文 · '+r.source.locator,`<p class="callout info">这是专为原型编写的虚构材料，不是外部文件或真实业务证据。</p><div class="source-page"><p class="eyebrow">原始材料样例 / ${esc(r.source.locator)}</p><h3>${esc(r.source.name)}</h3><p>以下高亮演示从知识回到原文位置的阅读方式。</p><p><mark>${esc(r.source.quote)}</mark></p><p class="evidence-meta">来源日期：${esc(r.source.date)} · 获取时间：${esc(r.source.observed)}</p></div>`)}});
document.addEventListener('keydown',e=>{if(!e.target.matches('[role=tab]'))return;const index=tabs.findIndex(([key])=>key===activeTab);let next;if(e.key==='ArrowRight')next=(index+1)%tabs.length;else if(e.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();activeTab=tabs[next][0];renderDetail();$('#tab-'+activeTab).focus()});
renderLibrary();
function keepActiveNavVisible(){const nav=$('.sidebar .global-nav'),active=$('.sidebar .nav-active');if(nav.clientHeight&&active.getBoundingClientRect().bottom>nav.getBoundingClientRect().bottom)nav.scrollTop+=active.getBoundingClientRect().bottom-nav.getBoundingClientRect().bottom+16}
keepActiveNavVisible();
window.addEventListener('resize',keepActiveNavVisible);
